@import "tailwindcss";

@theme {
  --color-relis-navy: #2a3f54;
  --color-relis-slate: #34495e;
  --color-relis-teal: #1abb9c;
  --color-relis-blue: #3498db;
  --color-relis-purple: #9b59b6;
  --color-relis-red: #e74c3c;
  --color-relis-orange: #f39c12;
  --color-relis-bg: #f7f7f7;
  --color-relis-muted: #73879c;
  --color-relis-dark: #0b0d12;
  --color-relis-panel: #12161f;
}

body {
  background: var(--color-relis-dark);
  color: #e7edf3;
}

::selection {
  background: var(--color-relis-teal);
  color: #05201b;
}

.glow-teal {
  box-shadow: 0 0 0 1px rgba(26, 187, 156, 0.35), 0 8px 30px -8px rgba(26, 187, 156, 0.35);
}

