import { spawnSync } from "node:child_process";
import path from "node:path";
import { describe, expect, it } from "vitest";

const mainPath = path.join(import.meta.dirname, "main.ts");
const tsxBin = path.join(import.meta.dirname, "..", "..", "..", "node_modules", ".bin", "tsx");

function runMain(env: Record<string, string | undefined>) {
  return spawnSync(process.execPath, [tsxBin, mainPath], {
    env: { ...process.env, ...env, DATABASE_URL: env.DATABASE_URL, PORT: "0" },
    encoding: "utf8",
    timeout: 10_000,
  });
}

describe("api startup validates configuration before serving traffic", () => {
  it("exits non-zero with safe diagnostics when DATABASE_URL is missing", () => {
    const result = runMain({ DATABASE_URL: undefined });
    expect(result.status).not.toBe(0);
    expect(result.stderr).toContain("DATABASE_URL");
    expect(result.stderr).toContain("CONFIG_MISSING");
    expect(result.stdout).not.toContain("API listening");
  });

  it("starts and reports listening when configuration is valid", () => {
    const result = spawnSync(
      process.execPath,
      [
        "-e",
        `
        const { spawn } = require('node:child_process');
        const child = spawn(process.argv[1], [process.argv[2]], {
          env: { ...process.env, DATABASE_URL: 'postgresql://u:p@localhost:5432/db', PORT: '0' },
