/**
 * Runs once when the Next.js server process starts (dev and prod, Node
 * runtime), before it accepts traffic. This is the frontend's equivalent
 * of the api/worker main.ts startup validation.
 */
export async function register() {
  if (process.env.NEXT_RUNTIME !== "nodejs") return;

  const { loadWebServerConfig, loadWebPublicConfig, ConfigValidationError } = await import("@relis/config");

  try {
    loadWebServerConfig();
    loadWebPublicConfig();
  } catch (error) {
    if (error instanceof ConfigValidationError) {
      console.error(JSON.stringify({ message: "Configuration validation failed", ...error.toSafeDiagnostics() }));
      process.exit(1);
    }
    throw error;
  }
}

