1	#!/usr/bin/env node
2	/**
3	 * Standalone validation entry point for deployment processes. No CI/CD
4	 * pipeline exists yet in this repository (see project report), so this is
5	 * not wired into one — a future pipeline can shell out to it, e.g.:
6	 *
7	 *   pnpm --filter @relis/config check:env -- api
8	 */
9	import { ConfigValidationError } from "./errors";
10	import { loadApiConfig } from "./processes/api";
11	import { loadMigrationConfig } from "./processes/migration";
12	import { loadWebPublicConfig, loadWebServerConfig } from "./processes/web";
13	import { loadWorkerConfig } from "./processes/worker";
14	
15	/**
16	 * A `Map`, not a plain object: a plain object's lookups fall through to
17	 * `Object.prototype` (`toString`, `constructor`, `__proto__`, ...), which
18	 * are functions too and would be silently "found" and invoked as if they
