1	import { spawn } from "node:child_process";
2	import path from "node:path";
3	import { loadEnvConfig } from "@next/env";
4	import { ConfigValidationError, loadWebPublicConfig, loadWebServerConfig } from "@relis/config";
5	
6	/**
7	 * Gates every Next.js startup command (dev/build/start) behind our
8	 * configuration contract, running strictly BEFORE Next.js itself is even
9	 * spawned. This exists because validating from inside the Next process
10	 * (see ../src/instrumentation.ts) is too late for two things:
11	 *
12	 *  - With PORT=0, Next asks the OS for a free port and overwrites
13	 *    process.env.PORT with whatever it got *before* instrumentation runs,
14	 *    silently discarding our contract's `PORT` minimum. Validating the
15	 *    raw/effective PORT here, before Next ever sees it, catches this.
16	 *  - Next's own listener can already be bound and briefly accepting TCP
17	 *    connections before an in-process check has a chance to reject and
18	 *    exit. Refusing to spawn Next at all means no listener ever opens.
19	 *
20	 * instrumentation.ts still validates as defense in depth (e.g. for a
21	 * process that invokes `next` directly, bypassing this script), but this
22	 * script is the primary, documented gate — see relis/README.md and
23	 * packages/config/README.md for the build-time vs. runtime distinction
24	 * applied below.
25	 */
26	
27	const webRoot = path.join(import.meta.dirname, "..");
28	const mode = process.argv[2];
29	const passthroughArgs = process.argv.slice(3);
30	
31	if (mode !== "dev" && mode !== "build" && mode !== "start") {
32	  console.error(JSON.stringify({ message: "Usage: preflight <dev|build|start> [next args...]" }));
33	  process.exit(1);
34	}
35	
36	function parseCliPort(args: string[]): string | undefined {
37	  for (let i = 0; i < args.length; i++) {
38	    const arg = args[i];
39	    if (arg === "-p" || arg === "--port") return args[i + 1];
40	    if (arg?.startsWith("--port=")) return arg.slice("--port=".length);
41	  }
42	  return undefined;
43	}
44	
45	// Replicates Next.js's own .env loading precedence (.env.local, .env.<mode>,
46	// .env, ...) for the given mode, populating process.env the same way `next`
47	// itself would before it reads anything.
48	loadEnvConfig(webRoot, mode === "dev");
49	
50	const cliPort = parseCliPort(passthroughArgs);
51	const effectiveEnv: NodeJS.ProcessEnv = { ...process.env };
52	if (cliPort !== undefined) {
53	  // A CLI --port/-p flag overrides the environment, exactly like Next's own
54	  // precedence — so we must validate the value Next will actually use, not
55	  // just whatever PORT happens to be set to.
56	  effectiveEnv.PORT = cliPort;
57	}
58	
59	try {
60	  if (mode === "build") {
61	    // Build only embeds NEXT_PUBLIC_* values into the client bundle; it
62	    // never opens a listener, so server/runtime config (PORT, NODE_ENV) is
63	    // not this step's concern.
64	    loadWebPublicConfig(effectiveEnv);
65	  } else if (mode === "dev") {
66	    // Dev serves and re-embeds on every run: both matter up front.
67	    loadWebServerConfig(effectiveEnv);
68	    loadWebPublicConfig(effectiveEnv);
69	  } else {
70	    // start serves an already-built bundle. The public values it contains
71	    // were embedded at build time and are not re-read here — requiring
72	    // NEXT_PUBLIC_API_URL again at start would incorrectly imply that
73	    // changing it now could change what's already in the shipped client
74	    // JS, which it cannot. Only the server's own runtime config gates it.
75	    loadWebServerConfig(effectiveEnv);
76	  }
77	} catch (error) {
78	  if (error instanceof ConfigValidationError) {
79	    console.error(JSON.stringify({ message: "Configuration validation failed", step: mode, ...error.toSafeDiagnostics() }));
80	    process.exit(1);
81	  }
82	  throw error;
83	}
84	
85	const nextBin = path.join(webRoot, "node_modules", "next", "dist", "bin", "next");
86	const child = spawn(process.execPath, [nextBin, mode, ...passthroughArgs], {
87	  cwd: webRoot,
88	  stdio: "inherit",
89	  env: process.env,
90	});
91	
92	for (const signal of ["SIGINT", "SIGTERM"] as const) {
93	  process.on(signal, () => child.kill(signal));
94	}
95	
96	child.on("exit", (code, signal) => {
97	  process.exit(code ?? (signal ? 1 : 0));
98	});
