/**
 * Authoritative metadata for every environment variable known to the shared
 * configuration contract. Each process schema (see `processes/*.ts`) is
 * built from a subset of these fields, so a variable is defined exactly
 * once and reused wherever it applies.
 */

export const CONFIG_CATEGORIES = [
  "core",
  "network",
  "database",
  "web-public",
] as const;

export type ConfigCategory = (typeof CONFIG_CATEGORIES)[number];

export interface ConfigVariableMeta {
  /** Configuration category used for diagnostics grouping. */
  category: ConfigCategory;
  /** Whether the value must never be exposed to a browser bundle or logs. */
  secret: boolean;
  /** Short human-readable description for documentation and CLI output. */
  description: string;
}

export const ENV_VARIABLES = {
  NODE_ENV: {
    category: "core",
    secret: false,
    description: "Runtime environment mode (development, test, or production).",
  },
  PORT: {
    category: "network",
    secret: false,
    description: "TCP port the HTTP service listens on.",
  },
  DATABASE_URL: {
    category: "database",
    secret: true,
    description: "PostgreSQL connection string for the control database.",
  },
  NEXT_PUBLIC_API_URL: {
    category: "web-public",
    secret: false,
    description: "Base URL the browser uses to reach the API. Inlined into the client bundle.",
  },
} as const satisfies Record<string, ConfigVariableMeta>;

export type EnvVariableName = keyof typeof ENV_VARIABLES;

export function getVariableMeta(name: string): ConfigVariableMeta | undefined {
  return Object.prototype.hasOwnProperty.call(ENV_VARIABLES, name)
    ? ENV_VARIABLES[name as EnvVariableName]
    : undefined;
}

import type { ConfigCategory } from "./variables";

export type ConfigIssueCode = "CONFIG_MISSING" | "CONFIG_INVALID";

export interface ConfigIssue {
  /** Environment variable name. Never paired with its value. */
  variable: string;
  category: ConfigCategory | "unknown";
  code: ConfigIssueCode;
}

export interface SafeConfigDiagnostics {
  process: string;
  issues: ConfigIssue[];
}

/**
 * Thrown when a process's required configuration fails validation. The
 * message and every accessor here are built exclusively from variable
 * names, categories, and stable codes — never from the raw input values —
 * so this error is always safe to log or return from a diagnostics endpoint.
 */
export class ConfigValidationError extends Error {
  readonly process: string;
  readonly issues: ConfigIssue[];

  constructor(processName: string, issues: ConfigIssue[]) {
    const summary = issues
      .map((issue) => `${issue.variable} [${issue.category}]: ${issue.code}`)
      .join("; ");
    super(`Invalid configuration for "${processName}": ${summary}`);
    this.name = "ConfigValidationError";
    this.process = processName;
    this.issues = issues;
  }

  toSafeDiagnostics(): SafeConfigDiagnostics {
    return {
      process: this.process,
      issues: this.issues,
    };
  }
}

