29	function defaultBuildWeb(): number {
30	  const tsxBin = path.join(webDir, "node_modules", "tsx", "dist", "cli.mjs");
31	  return spawnAndWait(process.execPath, [tsxBin, path.join(webDir, "scripts", "preflight.ts"), "build"], webDir);
32	}
33	
34	/** Data-writing step: control-database migrations. */
35	function defaultMigrate(): number {
36	  return runMigration();
37	}
38	
39	/** Runtime step: start api, worker, and the already-built web server. */
40	function defaultStartServices(): number {
41	  const apiTsx = path.join(apiDir, "node_modules", "tsx", "dist", "cli.mjs");
42	  const workerTsx = path.join(workerDir, "node_modules", "tsx", "dist", "cli.mjs");
43	  const webNext = path.join(webDir, "node_modules", "next", "dist", "bin", "next");
44	
45	  const children: ChildProcess[] = [
46	    spawn(process.execPath, [apiTsx, path.join(apiDir, "src", "main.ts")], { cwd: apiDir, stdio: "inherit", env: process.env }),
47	    spawn(process.execPath, [workerTsx, path.join(workerDir, "src", "main.ts")], { cwd: workerDir, stdio: "inherit", env: process.env }),
48	    spawn(process.execPath, [webNext, "start"], { cwd: webDir, stdio: "inherit", env: process.env }),
49	  ];
50	
51	  const forward = (signal: NodeJS.Signals) => {
52	    for (const child of children) child.kill(signal);
53	  };
54	  process.on("SIGINT", () => forward("SIGINT"));
55	  process.on("SIGTERM", () => forward("SIGTERM"));
56	
57	  // Services are launched; each has its own startup validation gate
58	  // (main.ts / preflight.ts) and will exit non-zero on its own if its
59	  // configuration turns out to be invalid at that point. This step's job —
60	  // launching them after every prior gate passed — is done.
61	  return 0;
62	}
63	
64	const defaultDeps: DeployDeps = {
65	  validateAll: defaultValidateAll,
66	  buildWeb: defaultBuildWeb,
67	  migrate: defaultMigrate,
68	  startServices: defaultStartServices,
69	};
70	
71	/**
72	 * Minimal local deployment orchestration gate. No CI/CD platform, cloud
73	 * provider, or container architecture exists in this repository, so this
74	 * command IS the deployment entry point for now (see relis/README.md).
75	 *
76	 * Every process involved (api, worker, web server, web public, migration)
77	 * is validated together, in one aggregated pass, BEFORE the first side
78	 * effect — before the web bundle is built (which embeds config), before
79	 * migrations run (which write to the database), and before any service
80	 * starts (which accepts traffic). Any step failing stops every subsequent
81	 * step and propagates a nonzero exit code; steps are injectable so this can
82	 * be tested for ordering and short-circuiting without touching a real
83	 * database or actually building/starting anything.
84	 */
85	export function runDeploy(deps: DeployDeps = defaultDeps): number {
86	  try {
87	    deps.validateAll();
88	  } catch (error) {
89	    if (error instanceof ConfigValidationError) {
90	      console.error(JSON.stringify({ message: "Configuration validation failed", step: "deploy-preflight", ...error.toSafeDiagnostics() }));
91	      return 1;
92	    }
93	    throw error;
94	  }
95	
96	  const buildCode = deps.buildWeb();
97	  if (buildCode !== 0) return buildCode;
98	
99	  const migrateCode = deps.migrate();
100	  if (migrateCode !== 0) return migrateCode;
101	
102	  return deps.startServices();
103	}
