      return 1;
    }
    throw error;
  }

  const buildCode = deps.buildWeb(configs);
  if (buildCode !== 0) return buildCode;

  const migrateCode = deps.migrate();
  if (migrateCode !== 0) return migrateCode;

  return deps.startServices(configs);
