import { describe, expect, it, vi } from "vitest";
import { ConfigValidationError } from "@relis/config";
import { runDeploy, type DeployDeps } from "./run-deploy";

function makeDeps(overrides: Partial<DeployDeps> = {}): DeployDeps {
  return {
    validateAll: vi.fn(),
    buildWeb: vi.fn(() => 0),
    migrate: vi.fn(() => 0),
    startServices: vi.fn(() => 0),
    ...overrides,
  };
}

describe("runDeploy ordering and short-circuiting (spy-based, no real build/migrate/start)", () => {
  it("runs validate -> build -> migrate -> start, in that order, when every step succeeds", () => {
    const calls: string[] = [];
    const deps = makeDeps({
      validateAll: vi.fn(() => {
        calls.push("validate");
      }),
      buildWeb: vi.fn(() => {
        calls.push("build");
        return 0;
      }),
      migrate: vi.fn(() => {
        calls.push("migrate");
        return 0;
      }),
      startServices: vi.fn(() => {
        calls.push("start");
        return 0;
      }),
    });

    expect(runDeploy(deps)).toBe(0);
    expect(calls).toEqual(["validate", "build", "migrate", "start"]);
  });

  it("stops before build/migrate/start when validation fails — the first side effect never happens", () => {
    const deps = makeDeps({
      validateAll: vi.fn(() => {
        throw new ConfigValidationError("deploy", [
          { variable: "DATABASE_URL", category: "database", code: "CONFIG_MISSING" },
        ]);
      }),
    });

    expect(runDeploy(deps)).toBe(1);
    expect(deps.buildWeb).not.toHaveBeenCalled();
    expect(deps.migrate).not.toHaveBeenCalled();
    expect(deps.startServices).not.toHaveBeenCalled();
  });

  it("stops before migrate/start when the build step fails, propagating its exit code", () => {
    const deps = makeDeps({ buildWeb: vi.fn(() => 3) });

    expect(runDeploy(deps)).toBe(3);
    expect(deps.migrate).not.toHaveBeenCalled();
    expect(deps.startServices).not.toHaveBeenCalled();
  });

  it("stops before start when migrate fails, propagating its exit code — no service starts if the database write failed", () => {
    const deps = makeDeps({ migrate: vi.fn(() => 5) });

    expect(runDeploy(deps)).toBe(5);
    expect(deps.startServices).not.toHaveBeenCalled();
  });
});

